export function uiText(lang,key){return (UI[lang]||UI.en)[key]||UI.en[key]||key;}
export function demoText(demo,lang,key,age='adults',mode='interactive'){
  const data=(lang==='no'?COPY_NO:COPY_EN)[demo.id]||COPY_EN[demo.id]||{};
  const field={short:'short_title',title:'title',category:'category',summary:'summary',attribution:'attribution'}[key];
  if(field)return data[field]??demo[key]??'';
  if(key==='hint')return data.instructions?.[mode]?.[age]??data.instructions?.interactive?.adults??demo.hint??'';
  if(key==='reveal')return data.explanation?.[age]??data.explanation?.adults??demo.reveal??'';
  return lang==='no'?(DEMO_NO[demo.id]?.[key]||demo[key]):demo[key];
}
export function presentationCueText(demo,lang,age,index){
  const data=(lang==='no'?COPY_NO:COPY_EN)[demo.id]?.presentation?.[index];
  if(!data)return null;
  return {title:data.title||'',text:data.instruction?.[age]??data.instruction?.adults??''};
}
export function controlText(demo,control,lang){
  if(control.key==='presentationDuration')return {label:lang==='no'?'Visningstid i presentasjonen':control.label,options:control.options};
  if(lang!=='no')return {label:control.label,options:control.options};
  const tr=DEMO_NO[demo.id]||{},label=tr.controls?.[control.key]||control.label;
  const options=control.options?.map(([value,text])=>[value,tr.options?.[control.key]?.[value]||text]);
  return {label,options};
}
